-- Import completed workout history from 2026_08_04 Workouts.csv.
-- Generated by Codex on 2026-08-04.
--
-- This script intentionally does NOT delete public.workouts, public.workout_exercises,
-- public.workout_exercise_sets, public.training_plans, or public.training_plan_workouts.
-- It replaces completed workout history only: workout_sessions plus cascading
-- session_exercises and session_sets.
--
-- Safety behavior:
-- 1. Runs inside a transaction.
-- 2. Preflights that all imported exercise/equipment pairs exist in public.exercises.
-- 3. Creates permanent backup tables before deleting existing completed history.
-- 4. Raises before destructive changes if backup tables already exist.
--
-- To rollback after this script succeeds, run:
--   supabase/rollback_workout_history_import_2026_08_04.sql

begin;

set local timezone to 'America/Detroit';

create temp table _history_import_target_user (user_id uuid primary key) on commit drop;

insert into _history_import_target_user (user_id)
select id from auth.users where lower(email) = lower('ihgold@comcast.net');

do $$
begin
  if (select count(*) from _history_import_target_user) <> 1 then
    raise exception 'Expected exactly one auth.users row for %, found %', 'ihgold@comcast.net', (select count(*) from _history_import_target_user);
  end if;
  if to_regclass('public.workout_sessions_backup_20260804_workout_history_import') is not null
    or to_regclass('public.session_exercises_backup_20260804_workout_history_import') is not null
    or to_regclass('public.session_sets_backup_20260804_workout_history_import') is not null then
    raise exception 'Backup table(s) for 20260804_workout_history_import already exist. Stop to avoid overwriting rollback data.';
  end if;
end $$;

create temp table _history_import_workouts (id uuid primary key, source_key text not null unique, workout_name text not null, completed_at_text text not null, duration_seconds integer) on commit drop;
create temp table _history_import_exercises (exercise_import_id uuid primary key, workout_id uuid not null references _history_import_workouts(id) on delete cascade, position integer not null, exercise_name text not null, equipment text not null, superset_group text) on commit drop;
create temp table _history_import_sets (exercise_import_id uuid not null references _history_import_exercises(exercise_import_id) on delete cascade, set_number integer not null, actual_weight_value numeric, actual_weight_label text, actual_reps integer, actual_rir_value integer not null default 0, actual_rir_label text, actual_rir_numeric numeric not null default 0, is_drop_set boolean not null default false) on commit drop;

